script:
// Countdown (ds-metrics §14 — CountdownLabel): formatDuration(until − env.now) in `font` (default title, el16) + optional
// caption label (caption, el9), gap xs; env.now ticks every second while read. `expire` fires when the time is up: a
// 0×0 sentinel appears once nothing is left (right away if `until` is already past). appear re-fires whenever the
// sentinel is re-materialized (e.g. scrolled back into a lazy scroll), so `firedFor` remembers which `until` already
// fired — a new `until` re-arms it. If the whole instance is re-materialized its state resets and expire fires again.
param until: number
param format: "hms" | "ms" | "dhms" = "hms"
param label: string = ""
param font: textStyle = @type.title
event expire
state firedFor = -1
let left = max(until - env.now, 0)

on.appear:
if firedFor != until {
  firedFor = until
  emit expire
}
